import java.util.ArrayList;
import java.util.List;

final class Main {

    private Main() {
    }

    public static void insertionSort(List<Float> bucket) {
        for (int i = 1; i < bucket.size(); ++i) {
            float key = bucket.get(i);
            int j = i - 1;
            while (j >= 0 && bucket.get(j) > key) {
                bucket.set(j + 1, bucket.get(j));
                j--;
            }
            bucket.set(j + 1, key);
        }
    }

    public static void bucketSort(float[] values) {
        int bucketCount = values.length;
        List<Float>[] buckets = createBuckets(bucketCount);

        distributeValues(values, buckets);
        sortBuckets(buckets);
        writeBucketsBack(values, buckets);
    }

    @SuppressWarnings("unchecked")
    private static List<Float>[] createBuckets(int bucketCount) {
        List<Float>[] buckets = new ArrayList[bucketCount];
        for (int i = 0; i < bucketCount; i++) {
            buckets[i] = new ArrayList<>();
        }
        return buckets;
    }

    private static void distributeValues(float[] values, List<Float>[] buckets) {
        int bucketCount = buckets.length;
        for (float value : values) {
            int bucketIndex = (int) (bucketCount * value);
            buckets[bucketIndex].add(value);
        }
    }

    private static void sortBuckets(List<Float>[] buckets) {
        for (List<Float> bucket : buckets) {
            insertionSort(bucket);
        }
    }

    private static void writeBucketsBack(float[] values, List<Float>[] buckets) {
        int index = 0;
        for (List<Float> bucket : buckets) {
            for (float value : bucket) {
                values[index++] = value;
            }
        }
    }

    private static void printValues(float[] values) {
        for (float value : values) {
            System.out.print(value + " ");
        }
    }

    public static void main(String[] args) {
        float[] values = {0.897f, 0.565f, 0.656f, 0.1234f, 0.665f, 0.3434f};
        bucketSort(values);

        System.out.println("Sorted array is:");
        printValues(values);
    }
}

